class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int sumDecoded(long[] nums) {
    long total = 0;
    for (long v : nums) {
      int width = (int) (v % 10);
      String d = Long.toString(v / 10);
      long x = Long.parseLong(d.substring(0, width)), y = Long.parseLong(d.substring(width));
      total = (total + pow(x, y)) % MOD;
    }
    return (int) total;
  }
}
